import json, urllib.request
spec = json.load(urllib.request.urlopen('https://api.hookdeck.com/latest/openapi'))
for path, methods in spec['paths'].items():
    if 'issue-triggers' in path:
        print(path)
        for method, op in methods.items():
            print(' ', method, op.get('operationId'))
            if 'requestBody' in op:
                print('   body schema ref', op['requestBody']['content']['application/json']['schema'])
PY"

