input.command:
/bin/bash -lc 'set -e
curl -sS -u "$HOOKDECK_API_KEY:" -H '"'Accept: application/json' \\
  'https://api.hookdeck.com/2025-07-01/issue-triggers?name=fulfilment-delivery-failures&limit=10' \\
  -o /tmp/fulfilment-trigger-verify.json
node <<'NODE'
const fs=require('fs');
const result=JSON.parse(fs.readFileSync('/tmp/fulfilment-trigger-verify.json'));
if (result.count "'!== 1 || result.models.length !== 1) throw new Error(`Expected one trigger, got ${result.count}`);
const trigger=result.models[0];
const expectedConnection='"'web_YMPYDXqVVOGv';
if (trigger.type "'!== '"'delivery') throw new Error('Wrong trigger type');
if (trigger.configs?.strategy "'!== '"'final_attempt') throw new Error('Wrong strategy');
if ("'!trigger.configs?.connections?.includes(expectedConnection)) throw new Error('"'Wrong connection scope');
if ("'!trigger.channels?.email) throw new Error('"'Email channel missing');
if (trigger.disabled_at "'!== null) throw new Error('"'Trigger is disabled');
console.log(JSON.stringify({
  verified: true,
  id: trigger.id,
  name: trigger.name,
  active: trigger.disabled_at === null,
  condition: "'`${trigger.type}:${trigger.configs.strategy}`,
  connection_id: expectedConnection,
  channel: '"'email',
  created_at: trigger.created_at
}, null, 2));
NODE"

